<?php
require_once __DIR__ . '/../includes/functions.php'; require_admin();
$pdo=db(); $q=trim($_GET['q']??''); $status=trim($_GET['status']??'');
$allowed=['pending_payment','confirmed','checked_in','completed','cancelled'];
if($_SERVER['REQUEST_METHOD']==='POST') { verify_csrf(); $id=(int)($_POST['booking_id']??0); $new=$_POST['status']??''; $result=null; if(in_array($new,$allowed,true)){ if($new==='confirmed') $result=set_booking_status_and_notify($pdo,$id,$new); else { $st=$pdo->prepare('UPDATE bookings SET status=? WHERE id=?'); $st->execute([$new,$id]); $result=['message'=>'Reservation updated.']; } } redirect('/admin/reservations.php?updated=1&msg='.urlencode($result['message']??'Reservation updated.')); }
$sql='SELECT b.*,r.name room_name,(SELECT COALESCE(SUM(pr.amount),0) FROM payment_records pr WHERE pr.booking_id=b.id AND pr.status="verified") verified_paid FROM bookings b JOIN rooms r ON r.id=b.room_id WHERE 1=1'; $args=[];
if($q!==''){ $sql.=' AND (b.booking_code LIKE ? OR b.guest_name LIKE ? OR b.guest_email LIKE ? OR b.guest_phone LIKE ?)'; $like='%'.$q.'%'; array_push($args,$like,$like,$like,$like); }
if(in_array($status,$allowed,true)){ $sql.=' AND b.status=?'; $args[]=$status; }
$sql.=' ORDER BY b.created_at DESC LIMIT 300'; $st=$pdo->prepare($sql);$st->execute($args);$bookings=$st->fetchAll();
$pageTitle='Guest & reservations'; include __DIR__.'/../includes/header.php'; ?>
<section class="admin-page container"><div class="admin-heading"><div><p class="eyebrow">MODULE 3 · GUEST OPERATIONS</p><h1>Guests & <em>reservations.</em></h1><p class="muted">Search guest records, review stays, and update reservation status.</p></div><div class="admin-actions"><a class="button button-outline" href="<?= BASE_URL ?>/admin/index.php">← Dashboard</a><a class="text-link" href="<?= BASE_URL ?>/admin/logout.php">Sign out ↗</a></div></div>
<?php if(isset($_GET['updated'])):?><div class="notice notice-success"><?= e($_GET['msg'] ?? 'Reservation updated.') ?></div><?php endif;?>
<div class="admin-table-wrap"><div class="table-heading"><div><p class="eyebrow">BOOKING DIRECTORY</p><h2><?= count($bookings) ?> matching reservation(s)</h2></div></div><form class="report-filters" method="get" style="display:flex;gap:12px;flex-wrap:wrap;padding:0 24px 22px"><input name="q" value="<?= e($q) ?>" placeholder="Search code, guest, email, phone" style="flex:1;min-width:220px;padding:12px;border:1px solid var(--line)"><select name="status" style="padding:12px;border:1px solid var(--line)"><option value="">All statuses</option><?php foreach($allowed as $a):?><option value="<?= $a ?>" <?= $status===$a?'selected':'' ?>><?= ucfirst(str_replace('_',' ',$a)) ?></option><?php endforeach;?></select><button class="button button-dark">Search</button><a class="button button-outline" href="<?= BASE_URL ?>/admin/reservations.php">Reset</a></form><div class="table-scroll"><table><thead><tr><th>Reference / Guest</th><th>Room / Dates</th><th>Total</th><th>Verified payments</th><th>Status</th><th>Update</th></tr></thead><tbody><?php foreach($bookings as $b):?><tr><td><strong><?= e($b['booking_code']) ?></strong><small><?= e($b['guest_name']) ?><br><?= e($b['guest_email']) ?><br><?= e($b['guest_phone']??'') ?></small></td><td><?= e($b['room_name']) ?><small><?= e($b['check_in']) ?> → <?= e($b['check_out']) ?> · <?= (int)$b['nights'] ?> night(s)</small></td><td><?= money($b['total_amount']) ?></td><td><?= money($b['verified_paid']) ?><small>Balance: <?= money(max(0,(float)$b['total_amount']-(float)$b['verified_paid'])) ?></small></td><td><span class="status-pill"><?= e($b['status']) ?></span></td><td><form method="post" class="inline-status"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="booking_id" value="<?= (int)$b['id'] ?>"><select name="status"><?php foreach($allowed as $a):?><option value="<?= $a ?>" <?= $b['status']===$a?'selected':'' ?>><?= ucfirst(str_replace('_',' ',$a)) ?></option><?php endforeach;?></select><button class="small-button">Save</button></form><a class="text-link" href="<?= BASE_URL ?>/admin/payments.php?booking=<?= (int)$b['id'] ?>">Payments</a></td></tr><?php endforeach;?><?php if(!$bookings):?><tr><td colspan="6">No reservations match your search.</td></tr><?php endif;?></tbody></table></div></div></section>
